    /// See [`Table`] for layout rules.
    pub fn render(&self, frame: &mut Frame, rect: Rect) {
        let (computed_layout, spacer_width) = {
            // pick the largest possible layout, constrained by the available width
            let &(_, layout) = self
                .width_cutoffs
                .iter()
